    state: &mut SlotState,
    pinned: &PinnedCall,
    failed: bool,
) -> Result<()> {
    if state.active_calls.get(&pinned.call_id) != Some(pinned) {
        bail!("runtime active call changed during completion");
    }
    let requests_completed = state
        .requests_completed
        .checked_add(1)
        .context("runtime completed request counter overflow")?;
    let requests_failed = if failed {
        state
            .requests_failed
            .checked_add(1)
            .context("runtime failed request counter overflow")?
    } else {
        state.requests_failed
    };
    let epoch = state
        .epochs
        .get_mut(&pinned.epoch)
        .context("pinned epoch is missing")?;
    let active_leases = epoch
        .active_leases
        .checked_sub(1)
